primaryQuery:
run: order_items -> {
  group_by: order_id
  aggregate: line_items is count()
} -> {
  aggregate:
    orders is count()
    multi_item_orders is count() { where: line_items > 1 }
} -> {
  select:
    orders
    multi_item_orders
    multi_item_share is round(multi_item_orders / orders, 4)
}

verifyQuery:
run: order_items -> {
  group_by: order_id
  aggregate: line_items is count()
} -> {
  group_by: line_items
  aggregate: orders_with_n is count()
} -> {
  aggregate:
    orders is orders_with_n.sum()
    multi_item_orders is orders_with_n.sum() { where: line_items > 1 }
} -> {
  select:
    orders
    multi_item_orders
    multi_item_share is round(multi_item_orders / orders, 4)
}
